import { useEffect } from "react";
import { useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";

const ProtectedRoute = ({ children }) => {
  const { isAuthenticated, screenLoading } = useSelector(
    (state) => state.userReducer
  );
  const navigate = useNavigate();




  useEffect(() => {
    if (!screenLoading && !isAuthenticated) navigate('/login')
  }, [isAuthenticated, screenLoading]);

  return children;
};

export default ProtectedRoute;

import React, { useState, useEffect } from 'react'
import { FaUserAlt } from "react-icons/fa";
import { RiLockPasswordFill } from "react-icons/ri";
import { Link, useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { loginUserThunk } from '../../store/slice/user/userThunk';
const Login = () => {
  //
  const { isAuthenticated } = useSelector(
    (state) => state.userReducer
  );
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const [loginData, setloginData] = useState({
    username: "",
    password: ""
  })
  const handlechange = (e) => {
    setloginData({
      ...loginData,
      [e.target.name]: e.target.value
    })

  }
  useEffect(() => {
    if (isAuthenticated) navigate('/')
  }, [isAuthenticated]);


  const handleLogin = async () => {


    const response = await dispatch(loginUserThunk(loginData));
    if (response?.payload?.success) {
      navigate("/")
    }

  }
  return (
    <div className='w-full min-h-screen flex justify-center items-center p-4 selection:bg-primary/30'>
      <form onSubmit={(e) => { e.preventDefault(); handleLogin(); }} className='glass-card w-full max-w-md p-10 rounded-[2.5rem] flex flex-col gap-8 animate-float shadow-2xl relative overflow-hidden'>
        {/* Decorative background elements */}
        <div className='absolute -top-24 -right-24 w-48 h-48 bg-primary/20 blur-3xl rounded-full' />
        <div className='absolute -bottom-24 -left-24 w-48 h-48 bg-secondary/10 blur-3xl rounded-full' />

        <div className='text-center space-y-3 relative z-10'>
          <h1 className="text-5xl font-black tracking-tighter text-transparent bg-clip-text bg-gradient-to-br from-white via-primary to-secondary drop-shadow-sm uppercase">
            Welcome Back
          </h1>
          <p className='text-white/50 text-sm font-medium tracking-wide'>Enter your credentials to access your chats</p>
        </div>

        <div className='space-y-6 relative z-10'>
          <div className='space-y-2'>
            <label className='text-[10px] font-bold text-white/40 ml-1 uppercase tracking-[0.2em]'>Username</label>
            <div className="relative group">
              <FaUserAlt className='absolute left-4 top-1/2 -translate-y-1/2 text-white/20 group-focus-within:text-primary transition-colors' />
              <input
                type="text"
                required
                placeholder="Enter your username"
                name='username'
                autoComplete="username"
                onChange={handlechange}
                className='w-full bg-white/5 border border-white/10 focus:border-primary/50 rounded-2xl py-3.5 pl-12 pr-4 outline-none transition-all focus:bg-white/10 placeholder:text-white/10 text-sm font-medium'
              />
            </div>
          </div>

          <div className='space-y-2'>
            <div className='flex justify-between items-center'>
              <label className='text-[10px] font-bold text-white/40 ml-1 uppercase tracking-[0.2em]'>Password</label>
              <button type="button" className='text-[10px] font-bold text-primary/60 hover:text-primary uppercase tracking-wider transition-colors'>Forgot?</button>
            </div>
            <div className="relative group">
              <RiLockPasswordFill className='absolute left-4 top-1/2 -translate-y-1/2 text-white/20 group-focus-within:text-primary transition-colors' />
              <input
                type="password"
                required
                name='password'
                placeholder="••••••••"
                autoComplete="current-password"
                onChange={handlechange}
                className='w-full bg-white/5 border border-white/10 focus:border-primary/50 rounded-2xl py-3.5 pl-12 pr-4 outline-none transition-all focus:bg-white/10 placeholder:text-white/10 text-sm font-medium'
              />
            </div>
          </div>
        </div>

        <div className='space-y-5 relative z-10'>
          <button
            type="submit"
            className="btn w-full h-14 bg-gradient-to-r from-primary to-secondary border-none text-white font-bold rounded-2xl shadow-xl hover:scale-[1.02] active:scale-[0.98] transition-all pulse-glow"
          >
            Sign In
          </button>

          <p className='text-center text-xs text-white/30 font-medium'>
            Don't have an account?
            <Link to='/signup' className='text-white font-bold hover:text-primary transition-colors ml-1 border-b border-white/10 hover:border-primary'>Create Account</Link>
          </p>
        </div>
      </form>
    </div>
  )
}

export default Login

import React from 'react'
import MessageContainer from './MessageContainer.jsx'
import UserSidebar from './UserSidebar.jsx'
import { useDispatch, useSelector } from 'react-redux';
import { initializeSocket, setOnlineUsers } from '../../store/slice/socket/socketSlice.js';
import { setNewMessage } from '../../store/slice/message/messageSlice.js';
import { useEffect } from 'react';

const Home = () => {

  const { isAuthenticated, userProfile } = useSelector((state) => state.userReducer);
  const { socket } = useSelector((state) => state.socketReducer);

  const dispatch = useDispatch();
  useEffect(() => {
    if (!isAuthenticated) { return }
    dispatch(initializeSocket(userProfile?._id))
  }, [isAuthenticated]);


  useEffect(() => {
    if (!socket) return;

    socket.on("onlineUsers", (onlineUsers) => {

      dispatch(setOnlineUsers(onlineUsers));
    });
    socket.on("newMessage", (newMessage) => {
      dispatch(setNewMessage(newMessage));
    });
    return () => {
      socket.close()
    }
  }, [socket]);




  return (
    <div className='flex'>
      <UserSidebar />
      <MessageContainer />
    </div>
  )
}

export default Home

import React, { useEffect } from 'react'
import User from './User.jsx'
import Message from './Message'
import { useDispatch, useSelector } from 'react-redux';
import { getMessageThunk } from '../../store/slice/message/messageThunk.js';
import SendMessage from './SendMessage.jsx';
import Avatar from '../../component/Avatar.jsx';

const MessageContainer = () => {
  const { selectedUser } = useSelector((state) => state.userReducer);
  const { messages } = useSelector((state) => state.messageReducer);
  const { onlineUsers } = useSelector((state) => state.socketReducer);
  const isonline = onlineUsers?.includes(selectedUser?._id)


  const dispatch = useDispatch();
  useEffect(() => {
    if (selectedUser) {
      dispatch(getMessageThunk({ otherParticipantId: selectedUser?._id }))
    }

  }, [selectedUser])
  return (
    <div className='flex-1 flex flex-col h-screen relative bg-gradient-to-b from-white/[0.02] to-transparent'>
      {!selectedUser ? (
        <div className='flex-1 flex flex-col items-center justify-center text-center p-10'>
          <div className='w-24 h-24 bg-primary/10 rounded-full flex items-center justify-center mb-6 animate-pulse'>
            <span className='text-5xl'>💬</span>
          </div>
          <h2 className='text-3xl font-bold mb-2'>Welcome to SocketTalk</h2>
          <p className='text-white/40 max-w-xs'>Select a contact from the sidebar to start a secure, real-time conversation.</p>
        </div>
      ) : (
        <>
          {/* Header */}
          <div className='p-4 border-b border-white/5 bg-black/20 backdrop-blur-md flex items-center gap-4 sticky top-0 z-10'>
            <Avatar
              src={selectedUser?.avatar}
              name={selectedUser?.fullName || selectedUser?.username}
              isOnline={isonline}
              imgClassName="ring-2 ring-primary/30 ring-offset-2 ring-offset-black/20"
            />
            <div className='flex flex-col'>
              <h2 className='font-bold text-lg leading-tight'>{selectedUser?.fullName}</h2>
              <span className='text-xs text-primary font-medium'>Online</span>
            </div>
          </div>

          {/* Messages */}
          <div className='flex-1 overflow-y-auto p-6 space-y-4'>
            {messages?.length > 0 ? (
              messages.map((message) => (
                <Message key={message?._id} messageDetails={message} />
              ))
            ) : (
              <div className='h-full flex flex-col items-center justify-center opacity-20'>
                <span className='text-6xl mb-4'>✨</span>
                <p>Start your first message!</p>
              </div>
            )}
          </div>

          {/* Footer Input */}
          <div className='p-4 bg-gradient-to-t from-black/20 to-transparent'>
            <SendMessage />
          </div>
        </>
      )}
    </div>
  )
}

export default MessageContainer

import React, { useEffect, useState } from 'react'
import { IoIosSend } from "react-icons/io";
import { useDispatch, useSelector } from 'react-redux';
import { sendMessageThunk } from '../../store/slice/message/messageThunk';
const SendMessage = () => {
    const dispatch = useDispatch();
    const [message, setmessage] = useState("");
    const { selectedUser } = useSelector((state) => state.userReducer)
    const handleSend = (e) => {
        e.preventDefault();
        dispatch(sendMessageThunk({
            receiverId: selectedUser?._id,
            message
        }))
        setmessage("")
    }

    const handleChangeInput = (e) => {

        setmessage(e.target.value);
    }
    return (
        <form onSubmit={handleSend} className='max-w-4xl mx-auto'>
            <div className='relative flex items-center gap-2 bg-white/5 border border-white/10 p-2 pl-4 rounded-2xl focus-within:bg-white/10 focus-within:border-primary/50 transition-all shadow-xl backdrop-blur-sm'>
                <input
                    type="text"
                    placeholder="Write your message..."
                    value={message}
                    className="flex-1 bg-transparent border-none outline-none text-sm py-2"
                    onChange={handleChangeInput}
                />
                <button
                    type='submit'
                    disabled={!message.trim()}
                    className="btn btn-primary btn-circle btn-sm shadow-lg disabled:bg-white/5 disabled:text-white/20 transition-all active:scale-95"
                >
                    <IoIosSend className='text-lg' />
                </button>
            </div>
        </form>
    )
}

export default SendMessage

import React, { useEffect, useState } from 'react'
import { IoSearch } from "react-icons/io5";
import User from './User.jsx'
import { useDispatch, useSelector } from 'react-redux';
import { getOtherUsersThunk, getUserProfileThunk, logoutUserThunk } from '../../store/slice/user/userThunk.js';
import Avatar from '../../component/Avatar.jsx';

const UserSidebar = () => {
  const [searchValue, setSearchValue] = useState("");
  const dispatch = useDispatch();
  const [users, setUsers] = useState([]);
  const { otherUsers, userProfile } = useSelector((state) => state.userReducer);

  useEffect(() => {
    (async () => {
      dispatch(getUserProfileThunk());
      dispatch(getOtherUsersThunk());
    })();
  }, [])



  const handlelogout = async () => {
    dispatch(logoutUserThunk());
  }

  useEffect(() => {
    if (!searchValue) {
      setUsers(otherUsers);
    } else {
      setUsers(
        otherUsers.filter((user) => {
          return (
            user.username.toLowerCase().includes(searchValue.toLowerCase()) ||
            user.fullName
              .toLowerCase()
              .includes(searchValue.toLocaleLowerCase())
          );
        })
      );
    }
  }, [searchValue, otherUsers]);
  return (
    <div className='glass-sidebar min-w-[22rem] h-screen flex flex-col cursor-pointer transition-all duration-300'>
      <div className='p-6'>
        <h1 className='text-4xl font-black tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-primary to-secondary text-center mb-6'>
          SOCKET TALK
        </h1>

        <div className='relative group'>
          <input
            type="search"
            onChange={(e) => setSearchValue(e.target.value)}
            required
            placeholder="Search conversations..."
            className="input input-bordered w-full pl-12 bg-white/5 focus:bg-white/10 border-white/10 focus:border-primary/50 transition-all rounded-xl"
          />
          <IoSearch className='absolute left-4 top-1/2 -translate-y-1/2 text-2xl text-white/30 group-focus-within:text-primary transition-colors' />
        </div>
      </div>

      <div className='flex-1 overflow-y-auto px-4 space-y-1 py-4'>
        <div className='text-xs font-bold text-white/30 px-4 mb-2 uppercase tracking-widest'>Recent Chats</div>
        {users?.map((userDetails) => {
          return <User key={userDetails?._id} userDetails={userDetails} />;
        })}
        {users?.length === 0 && (
          <div className='text-center py-10 text-white/20 italic'>No users found</div>
        )}
      </div>

      <div className='p-4 bg-black/20 border-t border-white/5'>
        <div className='flex items-center justify-between gap-3 p-3 rounded-2xl bg-white/5 border border-white/5'>
          <div className='flex items-center gap-3'>
            <Avatar
              src={userProfile?.avatar}
              name={userProfile?.fullName || userProfile?.username}
              isOnline={true}
              imgClassName="ring-2 ring-primary ring-offset-2 ring-offset-black/20"
            />
            <div className='flex flex-col'>
              <span className='font-bold text-sm'>{userProfile?.username}</span>
              <span className='text-xs text-white/40'>Online</span>
            </div>
          </div>
          <button
            className="btn btn-ghost btn-sm text-error hover:bg-error/10"
            onClick={handlelogout}
          >
            Log Out
          </button>
        </div>
      </div>
    </div>
  )
}

export default UserSidebar

import { createSlice } from '@reduxjs/toolkit'

import { sendMessageThunk, getMessageThunk } from './messageThunk';


export const messageSlice = createSlice(
  {
    name: 'message',
    initialState: {
      messages: null,
      buttonLoading: false

    },
    reducers: { //synchronous functions only
      setNewMessage: (state, action) => {
        const oldMessages = state.messages ?? [];
        state.messages = [...oldMessages, action.payload];
      },
    },

    extraReducers: (builder) => {
      //send-message
      builder.addCase(sendMessageThunk.pending, (state, action) => {

        state.buttonLoading = true;

      });
      builder.addCase(sendMessageThunk.fulfilled, (state, action) => {

        state.buttonLoading = false;
        state.messages = [...state.messages, action.payload?.responseData]
      });
      builder.addCase(sendMessageThunk.rejected, (state, action) => {

        state.buttonLoading = false;
      });
      //get-message
      builder.addCase(getMessageThunk.pending, (state, action) => {

        state.buttonLoading = true;

      });
      builder.addCase(getMessageThunk.fulfilled, (state, action) => {


        state.messages = action.payload?.responseData?.message
        state.buttonLoading = false;
        // state.otherUsers = action.payload?.responseData;
      });
      builder.addCase(getMessageThunk.rejected, (state, action) => {

        state.buttonLoading = false;
      });


    }
  }
)
// Action creators are generated for each case reducer function



// Action creators are generated for each case reducer function
export const { setNewMessage } = messageSlice.actions

export default messageSlice.reducer

import { createSlice } from '@reduxjs/toolkit'
import { loginUserThunk, logoutUserThunk, registerUserThunk, getUserProfileThunk, getOtherUsersThunk } from './userThunk.js';


export const userSlice = createSlice(
  {
    name: 'user',
    initialState: {
      isAuthenticated: false,
      screenLoading: true,
      userProfile: null,
      buttonLoading: false,
      otherUsers: null,
      selectedUser: JSON.parse(localStorage.getItem("selectedUser")),
    },
    reducers: { //synchronous functions only
      setSelectedUser: (state, action) => {

        localStorage.setItem("selectedUser", JSON.stringify(action?.payload));

        state.selectedUser = action.payload;

      },
    },

    extraReducers: (builder) => {
      //get-other-user
      builder.addCase(getOtherUsersThunk.pending, (state, action) => {

        state.screenLoading = true;

      });
      builder.addCase(getOtherUsersThunk.fulfilled, (state, action) => {

        state.screenLoading = false;
        state.otherUsers = action.payload?.responseData;
      });
      builder.addCase(getOtherUsersThunk.rejected, (state, action) => {

        state.screenLoading = false;
      });
      //get-profile
      builder.addCase(getUserProfileThunk.pending, (state, action) => {


        state.screenLoading = true;
      });
      builder.addCase(getUserProfileThunk.fulfilled, (state, action) => {

        state.isAuthenticated = true;
        state.screenLoading = false;

        state.userProfile = action.payload?.responseData;

      });
      builder.addCase(getUserProfileThunk.rejected, (state, action) => {

        state.screenLoading = false;
      });
      //logout
      builder.addCase(logoutUserThunk.pending, (state, action) => {

        state.buttonLoading = true
      }),
        builder.addCase(logoutUserThunk.fulfilled, (state, action) => {

          state.userProfile = null;
          state.buttonLoading = false
          state.isAuthenticated = false
          state.screenLoading = false;
          state.otherUsers = null,
            state.selectedUser = null,
            localStorage.clear();
        }),
        builder.addCase(logoutUserThunk.rejected, (state, action) => {

          state.buttonLoading = false
        })
      //registration
      builder.addCase(registerUserThunk.pending, (state, action) => {

        state.isAuthenticated = false;
        state.buttonLoading = true
      }),
        builder.addCase(registerUserThunk.fulfilled, (state, action) => {

          state.userProfile = action.payload?.responseData?.user;
          state.buttonLoading = false;
          state.isAuthenticated = true
        }),
        builder.addCase(registerUserThunk.rejected, (state, action) => {

          state.buttonLoading = false
        })
      //login user
      builder.addCase(loginUserThunk.pending, (state, action) => {

        state.isAuthenticated = false;
        state.buttonLoading = true;
      }),
        builder.addCase(loginUserThunk.fulfilled, (state, action) => {

          state.userProfile = action.payload?.responseData?.user;
          state.buttonLoading = false
          state.isAuthenticated = true;
        }),
        builder.addCase(loginUserThunk.rejected, (state, action) => {

          state.buttonLoading = false
          state.isAuthenticated = false
        })
    }
  }
)
// Action creators are generated for each case reducer function



// Action creators are generated for each case reducer function
export const { setSelectedUser } = userSlice.actions

export default userSlice.reducer
